import{H as e,Q as t,R as n,b as r,h as i,t as a,v as o,x as s,y as c}from"./app-C7UVirDn.js";import"./sync_en_04-CUFBh7WD.js";import"./data-sync-new-BR08zBXF.js";var l=JSON.parse(`{"path":"/UserGuide/latest-Table/User-Manual/Data-Sync_apache.html","title":"Data Sync","lang":"en-US","frontmatter":{"description":"Data Sync Data synchronization is a typical requirement in the Industrial Internet of Things (IIoT). Through data synchronization mechanisms, data sharing between IoTDB instance...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Data Sync\\",\\"image\\":[\\"https://iotdb.apache.org/img/data-sync-new.png\\",\\"https://iotdb.apache.org/img/Data-Sync02.png\\",\\"https://iotdb.apache.org/img/e1.png\\",\\"https://iotdb.apache.org/img/e2.png\\",\\"https://iotdb.apache.org/img/sync_en_03.png\\",\\"https://iotdb.apache.org/img/sync_en_04.png\\"],\\"dateModified\\":\\"2026-08-12T04:00:42.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://iotdb.apache.org/UserGuide/latest-Table/User-Manual/Data-Sync_apache.html"}],["meta",{"property":"og:site_name","content":"IoTDB Website"}],["meta",{"property":"og:title","content":"Data Sync"}],["meta",{"property":"og:description","content":"Data Sync Data synchronization is a typical requirement in the Industrial Internet of Things (IIoT). Through data synchronization mechanisms, data sharing between IoTDB instance..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://iotdb.apache.org/img/data-sync-new.png"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"property":"og:locale:alternate","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-12T04:00:42.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-12T04:00:42.000Z"}],["link",{"rel":"alternate","hreflang":"zh-cn","href":"https://iotdb.apache.org/zh/UserGuide/latest-Table/User-Manual/Data-Sync_apache.html"}]]},"git":{"createdTime":1740039395000,"updatedTime":1786507242000,"contributors":[{"name":"leto-b","username":"leto-b","email":"bingqian.bai@timecho.com","commits":25,"url":"https://github.com/leto-b"},{"name":"W1y1r","username":"W1y1r","email":"150988475+W1y1r@users.noreply.github.com","commits":2,"url":"https://github.com/W1y1r"},{"name":"leto-bbq","username":"leto-bbq","email":"bingqian.bai@timecho.com","commits":2,"url":"https://github.com/leto-bbq"}]},"readingTime":{"minutes":15.88,"words":4765},"filePathRelative":"UserGuide/latest-Table/User-Manual/Data-Sync_apache.md","autoDesc":true}`),u={name:`Data-Sync_apache.md`};function d(a,l,u,d,f,p){let m=e(`RouteLink`);return n(),o(`div`,null,[l[9]||=c(`<h1 id="data-sync" tabindex="-1"><a class="header-anchor" href="#data-sync"><span>Data Sync</span></a></h1><p>Data synchronization is a typical requirement in the Industrial Internet of Things (IIoT). Through data synchronization mechanisms, data sharing between IoTDB instances can be achieved, enabling the establishment of a complete data pipeline to meet needs such as internal and external network data exchange, edge-to-cloud synchronization, data migration, and data backup.</p><h2 id="_1-functional-overview" tabindex="-1"><a class="header-anchor" href="#_1-functional-overview"><span>1. Functional Overview</span></a></h2><h3 id="_1-1-data-synchronization" tabindex="-1"><a class="header-anchor" href="#_1-1-data-synchronization"><span>1.1 Data Synchronization</span></a></h3><p>A data synchronization task consists of three stages:</p><figure><img src="/img/data-sync-new.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><ul><li>Source Stage: This stage is used to extract data from the source IoTDB, defined in the <code>source</code> section of the SQL statement.</li><li>Process Stage: This stage is used to process the data extracted from the source IoTDB, defined in the <code>processor</code> section of the SQL statement.</li><li>Sink Stage: This stage is used to send data to the target IoTDB, defined in the <code>sink</code> section of the SQL statement.</li></ul><p>By declaratively configuring these three parts in an SQL statement, flexible data synchronization capabilities can be achieved. Currently, data synchronization supports the synchronization of the following information, and you can select the synchronization scope when creating a synchronization task (the default is data.insert, which means synchronizing newly written data):</p><table style="text-align:left;"><tbody><tr><th>Synchronization Scope</th><th>Synchronization Content </th><th>Description</th></tr><tr><td colspan="2">all</td><td>All scopes</td></tr><tr><td rowspan="2">data（Data）</td><td>insert</td><td>Synchronize newly written data</td></tr><tr><td>delete</td><td>Synchronize deleted data</td></tr><tr><td rowspan="3">schema</td><td>database</td><td>Synchronize database creation, modification or deletion operations</td></tr><tr><td>table</td><td>Synchronize table creation, modification or deletion operations</td></tr><tr><td>TTL</td><td>Synchronize the data retention time</td></tr><tr><td>auth</td><td>-</td><td>Synchronize user permissions and access control</td></tr></tbody></table><h3 id="_1-2-functional-limitations-and-notes" tabindex="-1"><a class="header-anchor" href="#_1-2-functional-limitations-and-notes"><span>1.2 Functional Limitations and Notes</span></a></h3><ul><li>Data synchronization between IoTDB of 1. x series version and IoTDB of 2. x and above series versions is not supported.</li><li>When performing data synchronization tasks, avoid executing any deletion operations to prevent inconsistencies between the two ends.</li><li>The <code>pipe</code> and <code>pipe plugins</code> for tree modes and table modes are designed to be isolated from each other. Before creating a <code>pipe</code>, it is recommended to first use the <code>show</code> command to query the built-in plugins available under the current <code>-sql_dialect</code> parameter configuration to ensure syntax compatibility and functional support.</li><li>When Pipe fails to write data to the sink due to field type mismatches, IoTDB automatically converts the data to the field types defined in the existing sink schema and retries the write operation to improve synchronization success rate. This feature is controlled by the parameter <code>sink.exception.data.convert-on-type-mismatch</code>. Refer to the subsequent sink parameter table for detailed parameter descriptions.</li></ul><p>The conversion rules for type mismatches are as follows:</p><table><thead><tr><th>Source Type</th><th>Target Type</th><th>Conversion Rule</th></tr></thead><tbody><tr><td>Numeric Type</td><td>Numeric Type</td><td>Convert to the target numeric type. Truncation, precision loss, or overflow may occur.</td></tr><tr><td>Numeric Type</td><td>BOOLEAN</td><td><code>0</code> is converted to <code>false</code>; non-zero values are converted to <code>true</code>.</td></tr><tr><td>BOOLEAN</td><td>Numeric Type</td><td><code>true</code> is converted to <code>1</code>; <code>false</code> is converted to <code>0</code>.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>BOOLEAN</td><td>Parse the string into a BOOLEAN value.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>Numeric Type</td><td>Parse the string into the target numeric type. If parsing fails, write the default value <code>0</code>, <code>0L</code>, or <code>0.0</code>.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>TIMESTAMP</td><td>Parse the string into a TIMESTAMP value. If parsing fails, write the default value <code>0L</code>.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>DATE</td><td>Parse the string into a DATE value. If parsing fails, write the default date <code>1970-01-01</code>.</td></tr><tr><td>Invalid Numeric Value</td><td>DATE</td><td>If conversion to a valid DATE fails, write the default date <code>1970-01-01</code>.</td></tr><tr><td>DATE</td><td>TIMESTAMP</td><td>Convert to the timestamp of 00:00 (UTC) on the same day.</td></tr><tr><td>TIMESTAMP</td><td>DATE</td><td>Convert to the corresponding date in UTC.</td></tr></tbody></table><blockquote><p><strong>Note</strong>: Automatic conversion is performed based on the existing sink schema and will <strong>not</strong> modify the sink schema. This feature prioritizes continuous data synchronization, which may result in precision loss or writing of default values.</p></blockquote><h2 id="_2-usage-instructions" tabindex="-1"><a class="header-anchor" href="#_2-usage-instructions"><span>2. Usage Instructions</span></a></h2><p>A data synchronization task can be in one of three states: RUNNING, STOPPED, and DROPPED. The state transitions of the task are illustrated in the diagram below:</p><figure><img src="/img/Data-Sync02.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>After creation, the task will start directly. Additionally, if the task stops due to an exception, the system will automatically attempt to restart it.</p><p>We provide the following SQL statements for managing the state of synchronization tasks.</p><h3 id="_2-1-create-a-task" tabindex="-1"><a class="header-anchor" href="#_2-1-create-a-task"><span>2.1 Create a Task</span></a></h3><p>Use the <code>CREATE PIPE</code> statement to create a data synchronization task. Among the following attributes, <code>PipeId</code> and <code>sink</code> are required, while <code>source</code> and <code>processor</code> are optional. Note that the order of the <code>SOURCE</code> and <code>SINK</code> plugins cannot be swapped when writing the SQL.</p><p>SQL Example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#E06C75;">[IF NOT EXISTS]</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span><span style="color:#7F848E;font-style:italic;"> -- PipeId is a unique name identifying the task</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Data extraction plugin (optional)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#E06C75;">  [&lt;parameter&gt; = &lt;value&gt;,]</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Data processing plugin (optional)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> PROCESSOR (</span></span>
<span class="line"><span style="color:#E06C75;">  [&lt;parameter&gt; = &lt;value&gt;,]</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Data transmission plugin (required)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#E06C75;">  [&lt;parameter&gt; = &lt;value&gt;,]</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>IF NOT EXISTS Semantics</strong>: Ensures that the creation command is executed only if the specified Pipe does not exist, preventing errors caused by attempting to create an already existing Pipe.</p><p><strong>Note</strong>:</p><p>Starting from V2.0.8, when creating a full data synchronization Pipe (e.g. Pipeid: <code>alldatapipe</code>), the system will automatically split it into two independent Pipes:</p><ul><li>History Pipe: The PipeId is the original name plus the suffix <code>_history</code> (e.g. <code>alldatapipe_history</code>). The source parameter carries the default configurations: <code>&#39;realtime.enable&#39;=&#39;false&#39;, &#39;inclusion&#39;=&#39;data.insert&#39;, &#39;inclusion.exclusion&#39;=&#39;&#39;</code></li><li>Realtime Pipe: The PipeId is the original name plus the suffix <code>_realtime</code> (e.g. <code>alldatapipe_realtime</code>). The source parameter carries the default configuration: <code>&#39;history.enable&#39;=&#39;false&#39;</code>. If metadata synchronization is configured, the Realtime Pipe will be responsible for sending the data.</li></ul>`,27),i(`p`,null,[l[1]||=r(`After successful creation, the original PipeId (e.g. `,-1),l[2]||=i(`code`,null,`alldatapipe`,-1),l[3]||=r(`) will no longer be a valid identifier. When performing task operations such as starting, stopping, deleting, or viewing, you must use the split independent PipeId (i.e. `,-1),l[4]||=i(`code`,null,`*_history`,-1),l[5]||=r(` or `,-1),l[6]||=i(`code`,null,`*_realtime`,-1),l[7]||=r(`). For operation examples, see the `,-1),s(m,{to:`/UserGuide/latest-Table/User-Manual/Data-Sync_apache.html#_2-5-view-task`},{default:t(()=>[...l[0]||=[r(`View Task`,-1)]]),_:1}),l[8]||=r(` section`,-1)]),l[10]||=c(`<h3 id="_2-2-start-a-task" tabindex="-1"><a class="header-anchor" href="#_2-2-start-a-task"><span>2.2 Start a Task</span></a></h3><p>After creation, the task directly enters the RUNNING state and does not require manual startup. However, if the task is stopped using the <code>STOP PIPE</code> statement, you need to manually start it using the <code>START PIPE</code> statement. If the task stops due to an exception, it will automatically restart to resume data processing:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">START</span><span style="color:#ABB2BF;"> PIPE</span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_2-3-stop-a-task" tabindex="-1"><a class="header-anchor" href="#_2-3-stop-a-task"><span>2.3 Stop a Task</span></a></h3><p>To stop data processing:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">STOP</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_2-4-delete-a-task" tabindex="-1"><a class="header-anchor" href="#_2-4-delete-a-task"><span>2.4 Delete a Task</span></a></h3><p>To delete a specified task:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">DROP</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#E06C75;">[IF EXISTS]</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>IF EXISTS Semantics</strong>: Ensures that the deletion command is executed only if the specified Pipe exists, preventing errors caused by attempting to delete a non-existent Pipe.</p><p><strong>Note</strong>: Deleting a task does not require stopping the synchronization task first.</p><h3 id="_2-5-view-tasks" tabindex="-1"><a class="header-anchor" href="#_2-5-view-tasks"><span>2.5 View Tasks</span></a></h3><p>To view all tasks:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">SHOW PIPES</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>To view a specific task:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">SHOW PIPE </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Example Output of <code>SHOW PIPES</code>:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------------+-----------------------+-------+----------+-------------+-----------------------------------------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                              ID|           CreationTime|  </span><span style="color:#C678DD;">State</span><span style="color:#ABB2BF;">|PipeSource|PipeProcessor|                                                   PipeSink|ExceptionMessage|RemainingEventCount|EstimatedRemainingSeconds|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------------+-----------------------+-------+----------+-------------+-----------------------------------------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|59abf95db892428b9d01c5fa318014ea|</span><span style="color:#D19A66;">2024</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">-17T14:</span><span style="color:#D19A66;">03</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">44</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">189</span><span style="color:#ABB2BF;">|RUNNING|        {}|           {}|{sink</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">iotdb-thrift-sink, </span><span style="color:#D19A66;">sink</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ip</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">127</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">sink</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">port</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">6668</span><span style="color:#ABB2BF;">}|                |                </span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">|                     </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">03</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------------+-----------------------+-------+----------+-------------+-----------------------------------------------------------+----------------+-------------------+-------------------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Column Descriptions</strong>:</p><ul><li><strong>ID</strong>: Unique identifier of the synchronization task.</li><li><strong>CreationTime</strong>: Time when the task was created.</li><li><strong>State</strong>: Current state of the task.</li><li><strong>PipeSource</strong>: Source of the data stream.</li><li><strong>PipeProcessor</strong>: Processing logic applied during data transmission.</li><li><strong>PipeSink</strong>: Destination of the data stream.</li><li><strong>ExceptionMessage</strong>: Displays exception information for the task.</li><li><strong>RemainingEventCount</strong> (statistics may have delays): Number of remaining events, including data and metadata synchronization events, as well as system and user-defined events.</li><li><strong>EstimatedRemainingSeconds</strong> (statistics may have delays): Estimated remaining time to complete the transmission based on the current event count and pipe processing rate.</li></ul><p>Example:</p><p>In V2.0.8 and later versions, create a full data synchronization task and view the task details.</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> create</span><span style="color:#ABB2BF;"> pipe alldatapipe </span><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> source(</span><span style="color:#98C379;">&#39;inclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;all&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;exclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;auth&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink(</span><span style="color:#98C379;">&#39;node-urls&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> show pipe alldatapipe_history</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+-----------------------+-------+---------------------------------------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                 ID|           CreationTime|  </span><span style="color:#C678DD;">State</span><span style="color:#ABB2BF;">|                                                                                               PipeSource|PipeProcessor|                  PipeSink|ExceptionMessage|RemainingEventCount|EstimatedRemainingSeconds|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+-----------------------+-------+---------------------------------------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|alldatapipe_history|</span><span style="color:#D19A66;">2025</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">-18T15:</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">16</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">697</span><span style="color:#ABB2BF;">|RUNNING|{exclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">auth, </span><span style="color:#D19A66;">history</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">true, inclusion</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">data</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">insert</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">inclusion</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">exclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">realtime</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">false}|           {}|{node-urls</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">127</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">6668</span><span style="color:#ABB2BF;">}|                |                  </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">|                     </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+-----------------------+-------+---------------------------------------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> show pipe alldatapipe_realtime</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------+-----------------------+-------+---------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                  ID|           CreationTime|  </span><span style="color:#C678DD;">State</span><span style="color:#ABB2BF;">|                                                                 PipeSource|PipeProcessor|                  PipeSink|ExceptionMessage|RemainingEventCount|EstimatedRemainingSeconds|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------+-----------------------+-------+---------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|alldatapipe_realtime|</span><span style="color:#D19A66;">2025</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">-18T15:</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">16</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">312</span><span style="color:#ABB2BF;">|RUNNING|{exclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">auth, </span><span style="color:#D19A66;">history</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">false, inclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">all, </span><span style="color:#D19A66;">realtime</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">true}|           {}|{node-urls</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">127</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">6668</span><span style="color:#ABB2BF;">}|                |                  </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">|                     </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------+-----------------------+-------+---------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-6-modify-a-task" tabindex="-1"><a class="header-anchor" href="#_2-6-modify-a-task"><span>2.6 Modify a Task</span></a></h3><p>The <code>ALTER PIPE</code> statement dynamically updates an existing PIPE and supports modifying or replacing the configuration of source, processor, and sink.</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#E06C75;">[IF EXISTS]</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#C678DD;">    MODIFY</span><span style="color:#ABB2BF;">/</span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> SOURCE(...)</span></span>
<span class="line"><span style="color:#C678DD;">    MODIFY</span><span style="color:#ABB2BF;">/</span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> PROCESSOR(...)</span></span>
<span class="line"><span style="color:#C678DD;">    MODIFY</span><span style="color:#ABB2BF;">/</span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> SINK(...)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Description:</p><ul><li>Executing this operation does not change the running state of the PIPE. It is equivalent to keeping the processing progress of the original PipeId and creating a new PIPE at the original progress position.</li><li>The modify/replace parameters for source/processor/sink are all optional. If no modification parameter is specified, it is equivalent to deleting the current PIPE and recreating it with the original configuration and progress.</li><li>For a plugin specified with modify, the plugin&#39;s other parameters are retained, and only the given parameters are replaced or added.</li><li>For a plugin specified with replace, all parameters of the plugin are replaced directly.</li><li>When the [IF EXISTS] keyword is used, execution succeeds even if no Pipe with the same name exists, but no operation is actually performed.</li></ul><p>Example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#ABB2BF;"> PIPE A2B </span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> SINK (</span><span style="color:#98C379;">&#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_2-7-synchronization-plugins" tabindex="-1"><a class="header-anchor" href="#_2-7-synchronization-plugins"><span>2.7 Synchronization Plugins</span></a></h3><p>To make the architecture more flexible and adaptable to different synchronization scenarios, IoTDB supports plugin assembly in the synchronization task framework. The system provides some common pre-installed plugins, and you can also customize <code>processor</code> and <code>sink</code> plugins and load them into the IoTDB system.</p><p>To view the plugins available in the system (including custom and built-in plugins), use the following statement:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">SHOW PIPEPLUGINS</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Example Output:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> SHOW PIPEPLUGINS</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------------+----------+--------------------------------------------------------------------------------------------------+----------------------------------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                    PluginName|PluginType|                                                                                         ClassName|                                           PluginJar|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------------+----------+--------------------------------------------------------------------------------------------------+----------------------------------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|          DO-NOTHING-PROCESSOR|   Builtin|               </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">processor</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">donothing</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DoNothingProcessor</span><span style="color:#ABB2BF;">|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|               DO-NOTHING-SINK|   Builtin|               </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">connector</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">donothing</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DoNothingConnector</span><span style="color:#ABB2BF;">|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|                  IOTDB-SOURCE|   Builtin|                       </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">extractor</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">IoTDBExtractor</span><span style="color:#ABB2BF;">|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|             IOTDB-THRIFT-SINK|   Builtin|          </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">connector</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">thrift</span><span style="color:#ABB2BF;">.IoTDBThriftConnector|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|         IOTDB-THRIFT-</span><span style="color:#C678DD;">SSL</span><span style="color:#ABB2BF;">-SINK|   Builtin|       </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">connector</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">thrift</span><span style="color:#ABB2BF;">.IoTDBThriftSslConnector|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------------+----------+--------------------------------------------------------------------------------------------------+----------------------------------------------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Detailed introduction of pre-installed plugins is as follows (for detailed parameters of each plugin, please refer to the <a href="#reference-parameter-description">Parameter Description</a>:</p><table style="text-align:left;"><tbody><tr><th>Type</th><th>Custom Plugin</th><th>Plugin Name</th><th>Description</th></tr><tr><td>Source Plugin</td><td>Not Supported</td><td>iotdb-source</td><td>Default extractor plugin for extracting historical or real-time data from IoTDB. </td></tr><tr><td>processor Plugin</td><td>Supported</td><td>do-nothing-processor</td><td>Default processor plugin that does not process incoming data.</td></tr><tr><td rowspan="3">sink Plugin</td><td rowspan="3">Supported</td><td>do-nothing-sink</td><td>Does not process outgoing data.</td></tr><tr><td>iotdb-thrift-sink</td><td>Default sink plugin for data transmission between IoTDB instances (V2.0.0+). Uses Thrift RPC framework with a multi-threaded async non-blocking IO model, ideal for distributed target scenarios.</td></tr><tr><td>iotdb-thrift-ssl-sink</td><td>Used for data transmission between IoTDB instances (V2.0.0+). Uses Thrift RPC framework with a multi-threaded sync blocking IO model, suitable for high-security scenarios.</td></tr></tbody></table><h2 id="_3-usage-examples" tabindex="-1"><a class="header-anchor" href="#_3-usage-examples"><span>3. Usage Examples</span></a></h2><h3 id="_3-1-full-data-synchronization" tabindex="-1"><a class="header-anchor" href="#_3-1-full-data-synchronization"><span>3.1 Full Data Synchronization</span></a></h3><p>This example demonstrates synchronizing all data from one IoTDB to another. The data pipeline is shown below:</p><figure><img src="/img/e1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>In this example, we create a synchronization task named <code>A2B</code> to synchronize all data from IoTDB A to IoTDB B. The <code>iotdb-thrift-sink</code> plugin (built-in) is used, and the <code>node-urls</code> parameter is configured with the URL of the DataNode service port on the target IoTDB.</p><p>SQL Example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE A2B</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-partial-data-synchronization" tabindex="-1"><a class="header-anchor" href="#_3-2-partial-data-synchronization"><span>3.2 Partial Data Synchronization</span></a></h3><p>This example demonstrates synchronizing data within a specific historical time range (from August 23, 2023, 8:00 to October 23, 2023, 8:00) to another IoTDB. The data pipeline is shown below:</p><figure><img src="/img/e2.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>In this example, we create a synchronization task named <code>A2B</code>. First, we define the data range in the <code>source</code> configuration. Since we are synchronizing historical data (data that existed before the task was created), we need to configure the start time (<code>start-time</code>), end time (<code>end-time</code>), and the streaming mode (<code>mode.streaming</code>). The <code>node-urls</code> parameter is configured with the URL of the DataNode service port on the target IoTDB.</p><p>SQL Example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE A2B</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;source&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-source&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;mode.streaming&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;true&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;database-name&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;testdb.*&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;start-time&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;2023.08.23T08:00:00+00:00&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;end-time&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;2023.10.23T08:00:00+00:00&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">) </span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-async-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Where:</p><ul><li><code>mode.streaming</code>: Extraction mode for newly inserted data (after the pipe is created): Whether to extract data in streaming mode (if set to false, batch mode is used).</li><li><code>database-name</code>: Scope of Data Synchronization</li><li><code>start-time</code>: The event time at which data synchronization starts (inclusive).</li><li><code>end-time</code>: The event time at which data synchronization ends (inclusive).</li></ul><h3 id="_3-3-edge-to-cloud-data-transmission" tabindex="-1"><a class="header-anchor" href="#_3-3-edge-to-cloud-data-transmission"><span>3.3 Edge-to-Cloud Data Transmission</span></a></h3><p>This example demonstrates synchronizing data from multiple IoTDB clusters (B, C, D) to a central IoTDB cluster (A). The data pipeline is shown below:</p><figure><img src="/img/sync_en_03.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>To synchronize data from clusters B, C, and D to cluster A, the <code>database-name</code> and <code>table-name</code> parameters are used to restrict the data range.</p><p>SQL Example: On IoTDB B:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE BA</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;database-name&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;db_b.*&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;table-name&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;.*&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6667&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On IoTDB C ：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE CA</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;database-name&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;db_c.*&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;table-name&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;.*&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On IoTDB D：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE DA</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;database-name&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;db_d.*&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;table-name&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;.*&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6669&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The parameters in the preceding two examples have the same meanings as those below:</p><ul><li><code>database-name</code>: Restrict the database scope</li><li><code>table-name</code>: Match all tables</li><li><code>node-urls</code>: URL of the DataNode service port on the target IoTDB</li></ul><h3 id="_3-4-cascaded-data-transmission" tabindex="-1"><a class="header-anchor" href="#_3-4-cascaded-data-transmission"><span>3.4 Cascaded Data Transmission</span></a></h3><p>This example demonstrates cascading data transmission from IoTDB A to IoTDB B and then to IoTDB C. The data pipeline is shown below:</p><figure><img src="/img/sync_en_04.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>SQL Example: On IoTDB A:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE AB</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On IoTDB B:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE BC</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6669&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The parameters in the preceding example have the same meanings as those below:</p><ul><li><code>node-urls</code>: URL of the DataNode service port on the target IoTDB</li></ul><h3 id="_3-5-compressed-synchronization" tabindex="-1"><a class="header-anchor" href="#_3-5-compressed-synchronization"><span>3.5 Compressed Synchronization</span></a></h3><p>IoTDB supports specifying data compression methods during synchronization. The <code>compressor</code> parameter can be configured to enable real-time data compression and transmission. Supported algorithms include <code>snappy</code>, <code>gzip</code>, <code>lz4</code>, <code>zstd</code>, and <code>lzma2</code>. Multiple algorithms can be combined and applied in the configured order. The <code>rate-limit-bytes-per-second</code> parameter (supported in V1.3.3 and later) limits the maximum number of bytes transmitted per second (calculated after compression). If set to a value less than 0, there is no limit.</p><p><strong>SQL Example</strong>:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE A2B</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;compressor&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;snappy,lz4&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;rate-limit-bytes-per-second&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;1048576&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Where:</p><ul><li><code>node-urls</code>: URL of the DataNode service port on the target IoTDB</li></ul><h3 id="_3-6-encrypted-synchronization" tabindex="-1"><a class="header-anchor" href="#_3-6-encrypted-synchronization"><span>3.6 Encrypted Synchronization</span></a></h3><p>IoTDB supports SSL encryption during synchronization to securely transmit data between IoTDB instances. By configuring SSL-related parameters such as the certificate path (<code>ssl.trust-store-path</code>) and password (<code>ssl.trust-store-pwd</code>), data can be protected by SSL encryption during synchronization.</p><p><strong>SQL Example</strong>:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE A2B</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;iotdb-thrift-ssl-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6667&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;ssl.trust-store-path&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;pki/trusted&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;ssl.trust-store-pwd&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;root&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Where:</p><ul><li><code>node-urls</code>: URL of the DataNode service port on the target IoTDB</li><li><code>ssl.trust-store-path</code>: The trust store certificate path required to connect to the target DataNode</li><li><code>ssl.trust-store-pwd</code>: The trust store certificate password required to connect to the target DataNode</li></ul><h2 id="reference-notes" tabindex="-1"><a class="header-anchor" href="#reference-notes"><span>Reference: Notes</span></a></h2><p>You can adjust the parameters for data synchronization by modifying the IoTDB configuration file (<code>iotdb-system.properties</code>), such as the directory for storing synchronized data. The complete configuration is as follows:</p><div class="language-properties line-numbers-mode" data-highlighter="shiki" data-ext="properties" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-properties"><span class="line"><span style="color:#7F848E;font-style:italic;"># pipe_receiver_file_dir</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If this property is unset, system will save the data in the default relative path directory under the IoTDB folder(i.e., %IOTDB_HOME%/\${cn_system_dir}/pipe/receiver).</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If it is absolute, system will save the data in the exact location it points to.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If it is relative, system will save the data in the relative path directory it indicates under the IoTDB folder.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Note: If pipe_receiver_file_dir is assigned an empty string(i.e.,zero-size), it will be handled as a relative path.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For windows platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is a drive specifier followed by &quot;\\\\&quot;, or if its prefix is &quot;\\\\\\\\&quot;, then the path is absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># pipe_receiver_file_dir=data\\\\confignode\\\\system\\\\pipe\\\\receiver</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For Linux platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is &quot;/&quot;, then the path is absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#C678DD;">pipe_receiver_file_dir</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">data/confignode/system/pipe/receiver</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">####################</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">### Pipe Configuration</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">####################</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Uncomment the following field to configure the pipe lib directory.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: first_start</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For Windows platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is a drive specifier followed by &quot;\\\\&quot;, or if its prefix is &quot;\\\\\\\\&quot;, then the path is</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># pipe_lib_dir=ext\\\\pipe</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For Linux platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is &quot;/&quot;, then the path is absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#C678DD;">pipe_lib_dir</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">ext/pipe</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The maximum number of threads that can be used to execute the pipe subtasks in PipeSubtaskExecutor.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The actual value will be min(pipe_subtask_executor_max_thread_num, max(1, CPU core number / 2)).</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_subtask_executor_max_thread_num</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">5</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The connection timeout (in milliseconds) for the thrift client.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_sink_timeout_ms</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">900000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The maximum number of selectors that can be used in the sink.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Recommend to set this value to less than or equal to pipe_sink_max_client_number.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_sink_selector_number</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The maximum number of clients that can be used in the sink.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_sink_max_client_number</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">16</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The total bytes that all pipe sinks can transfer per second.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># When given a value less than or equal to 0, it means no limit.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># default value is -1, which means no limit.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: hot_reload</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: double</span></span>
<span class="line"><span style="color:#C678DD;">pipe_all_sinks_rate_limit_bytes_per_second</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">-1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="reference-parameter-description" tabindex="-1"><a class="header-anchor" href="#reference-parameter-description"><span>Reference: Parameter Description</span></a></h2><h3 id="source-parameter" tabindex="-1"><a class="header-anchor" href="#source-parameter"><span>source parameter</span></a></h3><table><thead><tr><th style="text-align:left;"><strong>Parameter</strong></th><th style="text-align:left;"><strong>Description</strong></th><th style="text-align:left;"><strong>Value Range</strong></th><th style="text-align:left;"><strong>Required</strong></th><th style="text-align:left;"><strong>Default Value</strong></th></tr></thead><tbody><tr><td style="text-align:left;">source</td><td style="text-align:left;">iotdb-source</td><td style="text-align:left;">String: iotdb-source</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">inclusion</td><td style="text-align:left;">Used to specify the range of data to be synchronized in the data synchronization task, including data, schema and auth</td><td style="text-align:left;">String:all, data(insert,delete), schema(database,table,ttl), auth</td><td style="text-align:left;">No</td><td style="text-align:left;">data.insert</td></tr><tr><td style="text-align:left;">inclusion.exclusion</td><td style="text-align:left;">Used to exclude specific operations from the range specified by inclusion, reducing the amount of data synchronized</td><td style="text-align:left;">String:all, data(insert,delete), schema(database,table,ttl), auth</td><td style="text-align:left;">No</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">mode.streaming</td><td style="text-align:left;">This parameter specifies the source of time-series data capture. It applies to scenarios where <code>mode.streaming</code> is set to <code>false</code>, determining the capture source for <code>data.insert</code> in <code>inclusion</code>. Two capture strategies are available: - <strong>true</strong>: Dynamically selects the capture type. The system adapts to downstream processing speed, choosing between capturing each write request or only capturing TsFile file sealing requests. When downstream processing is fast, write requests are prioritized to reduce latency; when processing is slow, only file sealing requests are captured to prevent processing backlogs. This mode suits most scenarios, optimizing the balance between processing latency and throughput. - <strong>false</strong>: Uses a fixed batch capture approach, capturing only TsFile file sealing requests. This mode is suitable for resource-constrained applications, reducing system load. <strong>Note</strong>: Snapshot data captured when the pipe starts will only be provided for downstream processing as files.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">mode.strict</td><td style="text-align:left;">Determines whether to strictly filter data when using the <code>time</code>, <code>path</code>, <code>database-name</code>, or <code>table-name</code> parameters: - <strong>true</strong>: Strict filtering. The system will strictly filter captured data according to the specified conditions, ensuring that only matching data is selected. - <strong>false</strong>: Non-strict filtering. Some extra data may be included during the selection process to optimize performance and reduce CPU and I/O consumption.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">mode.snapshot</td><td style="text-align:left;">This parameter determines the data capture mode, affecting the <code>data</code> in <code>inclusion</code>. Two modes are available: - <strong>true</strong>: Static data capture. A one-time data snapshot is taken when the pipe starts. Once the snapshot data is fully consumed, the pipe automatically terminates (executing <code>DROP PIPE</code> SQL automatically). - <strong>false</strong>: Dynamic data capture. In addition to capturing snapshot data when the pipe starts, it continuously captures subsequent data changes. The pipe remains active to process the dynamic data stream.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">database-name</td><td style="text-align:left;">When the user connects with <code>sql_dialect</code> set to <code>table</code>, this parameter can be specified. Determines the scope of data capture, affecting the <code>data</code> in <code>inclusion</code>. Specifies the database name to filter. It can be a specific database name or a Java-style regular expression to match multiple databases. By default, all databases are matched.</td><td style="text-align:left;">String: Database name or database regular expression pattern string, which can match uncreated or non - existent databases.</td><td style="text-align:left;">No</td><td style="text-align:left;">&quot;.*&quot;</td></tr><tr><td style="text-align:left;">table-name</td><td style="text-align:left;">When the user connects with <code>sql_dialect</code> set to <code>table</code>, this parameter can be specified. Determines the scope of data capture, affecting the <code>data</code> in <code>inclusion</code>. Specifies the table name to filter. It can be a specific table name or a Java-style regular expression to match multiple tables. By default, all tables are matched.</td><td style="text-align:left;">String: Data table name or data table regular expression pattern string, which can be uncreated or non - existent tables.</td><td style="text-align:left;">No</td><td style="text-align:left;">&quot;.*&quot;</td></tr><tr><td style="text-align:left;">start-time</td><td style="text-align:left;">Determines the scope of data capture, affecting the <code>data</code> in <code>inclusion</code>. Data with an event time <strong>greater than or equal to</strong> this parameter will be selected for stream processing in the pipe.</td><td style="text-align:left;">Long: [Long.MIN_VALUE, Long.MAX_VALUE](Unix bare timestamp)orString: ISO format timestamp supported by IoTDB</td><td style="text-align:left;">No</td><td style="text-align:left;">Long: [Long.MIN_VALUE, Long.MAX_VALUE](Unix bare timestamp)</td></tr><tr><td style="text-align:left;">end-time</td><td style="text-align:left;">Determines the scope of data capture, affecting the <code>data</code> in <code>inclusion</code>. Data with an event time <strong>less than or equal to</strong> this parameter will be selected for stream processing in the pipe.</td><td style="text-align:left;">Long: [Long.MIN_VALUE, Long.MAX_VALUE](Unix bare timestamp)orString: ISO format timestamp supported by IoTDB</td><td style="text-align:left;">No</td><td style="text-align:left;">Long: [Long.MIN_VALUE, Long.MAX_VALUE](Unix bare timestamp)</td></tr><tr><td style="text-align:left;">mods</td><td style="text-align:left;">Same as mods.enable, whether to send the MODS file for TSFile.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">skipIf</td><td style="text-align:left;">Which errors can be skipped? Currently only the insufficient privileges error.</td><td style="text-align:left;">String:no-privileges</td><td style="text-align:left;">No</td><td style="text-align:left;">no-privileges</td></tr></tbody></table><blockquote><p>💎 <strong>Note:</strong> The difference between the values of true and false for the data extraction mode <code>mode.streaming</code></p><ul><li>True (recommended): Under this value, the task will process and send the data in real-time. Its characteristics are high timeliness and low throughput.</li><li>False: Under this value, the task will process and send the data in batches (according to the underlying data files). Its characteristics are low timeliness and high throughput.</li></ul></blockquote><h3 id="sink-parameter" tabindex="-1"><a class="header-anchor" href="#sink-parameter"><span>sink parameter</span></a></h3><h4 id="iotdb-thrift-sink" tabindex="-1"><a class="header-anchor" href="#iotdb-thrift-sink"><span>iotdb-thrift-sink</span></a></h4><table><thead><tr><th style="text-align:left;"><strong>Parameter</strong></th><th style="text-align:left;"><strong>Description</strong></th><th style="text-align:left;">Value Range</th><th style="text-align:left;">Required</th><th style="text-align:left;">Default Value</th></tr></thead><tbody><tr><td style="text-align:left;">sink</td><td style="text-align:left;">iotdb-thrift-sink or iotdb-thrift-async-sink</td><td style="text-align:left;">String: iotdb-thrift-sink or iotdb-thrift-async-sink</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">node-urls</td><td style="text-align:left;">URLs of the DataNode service ports on the target IoTDB. (please note that the synchronization task does not support forwarding to its own service).</td><td style="text-align:left;">String. Example：&#39;127.0.0.1：6667，127.0.0.1：6668，127.0.0.1：6669&#39;， &#39;127.0.0.1：6667&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">user/username</td><td style="text-align:left;">Username for connecting to the target IoTDB. Must have appropriate permissions.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">password</td><td style="text-align:left;">Password for the username.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">batch.enable</td><td style="text-align:left;">Enables batch mode for log transmission to improve throughput and reduce IOPS.</td><td style="text-align:left;">Boolean: true, false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">batch.max-delay-seconds</td><td style="text-align:left;">Maximum delay (in seconds) for batch transmission.</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.max-delay-ms</td><td style="text-align:left;">Maximum delay (in ms) for batch transmission. (Available since v2.0.5)</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.size-bytes</td><td style="text-align:left;">Maximum batch size (in bytes) for batch transmission.</td><td style="text-align:left;">Long</td><td style="text-align:left;">No</td><td style="text-align:left;">16<em>1024</em>1024</td></tr><tr><td style="text-align:left;">compressor</td><td style="text-align:left;">The selected RPC compression algorithm. Multiple algorithms can be configured and will be adopted in sequence for each request.</td><td style="text-align:left;">String: snappy / gzip / lz4 / zstd / lzma2</td><td style="text-align:left;">No</td><td style="text-align:left;">&quot;&quot;</td></tr><tr><td style="text-align:left;">compressor.zstd.level</td><td style="text-align:left;">When the selected RPC compression algorithm is zstd, this parameter can be used to additionally configure the compression level of the zstd algorithm.</td><td style="text-align:left;">Int: [-131072, 22]</td><td style="text-align:left;">No</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">rate-limit-bytes-per-second</td><td style="text-align:left;">The maximum number of bytes allowed to be transmitted per second. The compressed bytes (such as after compression) are calculated. If it is less than 0, there is no limit.</td><td style="text-align:left;">Double: [Double.MIN_VALUE, Double.MAX_VALUE]</td><td style="text-align:left;">No</td><td style="text-align:left;">-1</td></tr><tr><td style="text-align:left;">load-tsfile-strategy</td><td style="text-align:left;">When synchronizing file data, ​​whether the receiver waits for the local load tsfile operation to complete before responding to the sender​​:<br>​​sync​​: Wait for the local load tsfile operation to complete before returning the response.<br>​​async​​: Do not wait for the local load tsfile operation to complete; return the response immediately.</td><td style="text-align:left;">String: sync / async</td><td style="text-align:left;">No</td><td style="text-align:left;">sync</td></tr><tr><td style="text-align:left;">format</td><td style="text-align:left;">The payload formats for data transmission include the following options:<br> - hybrid: The format depends on what is passed from the processor (either tsfile or tablet), and the sink performs no conversion.<br> - tsfile: Data is forcibly converted to tsfile format before transmission. This is suitable for scenarios like data file backup.<br> - tablet: Data is forcibly converted to tsfile format before transmission. This is useful for data synchronization when the sender and receiver have incompatible data types (to minimize errors).</td><td style="text-align:left;">String: hybrid / tsfile / tablet</td><td style="text-align:left;">No</td><td style="text-align:left;">hybrid</td></tr><tr><td style="text-align:left;">exception.data.convert-on-type-mismatch</td><td style="text-align:left;">Whether to enable automatic conversion when data types mismatch on the sink side</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr></tbody></table><h4 id="iotdb-thrift-ssl-sink" tabindex="-1"><a class="header-anchor" href="#iotdb-thrift-ssl-sink"><span>iotdb-thrift-ssl-sink</span></a></h4><table><thead><tr><th style="text-align:left;"><strong>Parameter</strong></th><th style="text-align:left;"><strong>Description</strong></th><th style="text-align:left;">Value Range</th><th style="text-align:left;">Required</th><th style="text-align:left;">Default Value</th></tr></thead><tbody><tr><td style="text-align:left;">sink</td><td style="text-align:left;">iotdb-thrift-ssl-sink</td><td style="text-align:left;">String: iotdb-thrift-ssl-sink</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">node-urls</td><td style="text-align:left;">URLs of the DataNode service ports on the target IoTDB. (please note that the synchronization task does not support forwarding to its own service).</td><td style="text-align:left;">String. Example：&#39;127.0.0.1：6667，127.0.0.1：6668，127.0.0.1：6669&#39;， &#39;127.0.0.1：6667&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">user/username</td><td style="text-align:left;">Username for connecting to the target IoTDB. Must have appropriate permissions.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">password</td><td style="text-align:left;">Password for the username.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">batch.enable</td><td style="text-align:left;">Enables batch mode for log transmission to improve throughput and reduce IOPS.</td><td style="text-align:left;">Boolean: true, false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">batch.max-delay-seconds</td><td style="text-align:left;">Maximum delay (in seconds) for batch transmission.</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.max-delay-ms</td><td style="text-align:left;">Maximum delay (in ms) for batch transmission. (Available since v2.0.5)</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.size-bytes</td><td style="text-align:left;">Maximum batch size (in bytes) for batch transmission.</td><td style="text-align:left;">Long</td><td style="text-align:left;">No</td><td style="text-align:left;">16<em>1024</em>1024</td></tr><tr><td style="text-align:left;">compressor</td><td style="text-align:left;">The selected RPC compression algorithm. Multiple algorithms can be configured and will be adopted in sequence for each request.</td><td style="text-align:left;">String: snappy / gzip / lz4 / zstd / lzma2</td><td style="text-align:left;">No</td><td style="text-align:left;">&quot;&quot;</td></tr><tr><td style="text-align:left;">compressor.zstd.level</td><td style="text-align:left;">When the selected RPC compression algorithm is zstd, this parameter can be used to additionally configure the compression level of the zstd algorithm.</td><td style="text-align:left;">Int: [-131072, 22]</td><td style="text-align:left;">No</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">rate-limit-bytes-per-second</td><td style="text-align:left;">Maximum bytes allowed per second for transmission (calculated after compression). Set to a value less than 0 for no limit.</td><td style="text-align:left;">Double: [Double.MIN_VALUE, Double.MAX_VALUE]</td><td style="text-align:left;">No</td><td style="text-align:left;">-1</td></tr><tr><td style="text-align:left;">load-tsfile-strategy</td><td style="text-align:left;">When synchronizing file data, ​​whether the receiver waits for the local load tsfile operation to complete before responding to the sender​​:<br>​​sync​​: Wait for the local load tsfile operation to complete before returning the response.<br>​​async​​: Do not wait for the local load tsfile operation to complete; return the response immediately.</td><td style="text-align:left;">String: sync / async</td><td style="text-align:left;">No</td><td style="text-align:left;">sync</td></tr><tr><td style="text-align:left;">ssl.trust-store-path</td><td style="text-align:left;">Path to the trust store certificate for SSL connection.</td><td style="text-align:left;">String: &#39;pki/trusted&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">ssl.trust-store-pwd</td><td style="text-align:left;">Password for the trust store certificate.</td><td style="text-align:left;">String: &#39;root&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">format</td><td style="text-align:left;">The payload formats for data transmission include the following options:<br> - hybrid: The format depends on what is passed from the processor (either tsfile or tablet), and the sink performs no conversion.<br> - tsfile: Data is forcibly converted to tsfile format before transmission. This is suitable for scenarios like data file backup.<br> - tablet: Data is forcibly converted to tsfile format before transmission. This is useful for data synchronization when the sender and receiver have incompatible data types (to minimize errors).</td><td style="text-align:left;">String: hybrid / tsfile / tablet</td><td style="text-align:left;">No</td><td style="text-align:left;">hybrid</td></tr><tr><td style="text-align:left;">exception.data.convert-on-type-mismatch</td><td style="text-align:left;">Whether to enable automatic conversion when data types mismatch on the sink side</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr></tbody></table>`,98)])}var f=a(u,[[`render`,d]]);export{l as _pageData,f as default};